const S = { tab: 'schede', cards: [], exercises: [], sessions: [], flow: { cardId: null, weekKey: null }, active: null, timer: null, tick: null, sessionTick: null, theme: localStorage.theme || 'system', missing: {}, focus: { on: false, blockIdx: 0, round: 1 }, sheet: null, sync: { config: null, lastSyncAt: null, status: 'idle', busy: false, pending: false, lastError: null } }; const $ = q => document.querySelector(q), byDom = id => document.getElementById(id), uid = () => crypto.randomUUID ? crypto.randomUUID() : 'id' + Date.now() + Math.random(), now = () => new Date().toISOString(), esc = (s = '') => String(s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
