const Store = { db: null, open() { return new Promise((res, rej) => { let r = indexedDB.open(DB, 2); r.onupgradeneeded = e => { let db = e.target.result;['cards', 'exercises', 'sessions', 'settings'].forEach(n => { if (!db.objectStoreNames.contains(n)) db.createObjectStore(n, { keyPath: 'id' }) }) }; r.onsuccess = e => { this.db = e.target.result; res() }; r.onerror = () => rej(r.error) }) }, all(n) { return new Promise(res => { let r = this.db.transaction(n).objectStore(n).getAll(); r.onsuccess = () => res(r.result || []) }) }, get(n, id) { return new Promise(res => { let r = this.db.transaction(n).objectStore(n).get(id); r.onsuccess = () => res(r.result) }) }, put(n, o) { return new Promise(res => { let r = this.db.transaction(n, 'readwrite').objectStore(n).put(o); r.onsuccess = () => res(o) }) }, del(n, id) { return new Promise(res => { let r = this.db.transaction(n, 'readwrite').objectStore(n).delete(id); r.onsuccess = () => res() }) }, clear(n) { return new Promise(res => { let r = this.db.transaction(n, 'readwrite').objectStore(n).clear(); r.onsuccess = () => res() }) } };
async function refresh() { S.cards = await Store.all('cards'); S.exercises = await Store.all('exercises'); S.sessions = await Store.all('sessions'); render() }
function label(k) { return String(k).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) }
function mapType(raw, sectionHint) {
    var t = String(raw || '').toLowerCase();
    var s = String(sectionHint || '').toLowerCase();
    if (t.includes('singolo') || t === 'esercizio_singolo') return 'Single';
    if (t.includes('superserie') || s === 'superserie') return 'Superset';
    if (t.includes('core') || s === 'core') return 'Core';
    if (t.includes('tabata') || s === 'tabata') return 'Tabata';
    if (t.includes('hiit') || s === 'hiit') return 'HIIT';
    if (t.includes('corpo_libero') || t.includes('corpo libero')) return 'Circuit';
    return 'Circuit';
}
function parseRestToSeconds(t) {
    var m = String(t || '').match(/(\d+)(?:-(\d+))?\s*sec/gi);
    if (!m) return 60;
    var nums = m.at(-1).match(/\d+/g).map(Number);
    return nums.length > 1 ? Math.round((nums[0] + nums[1]) / 2) : nums[0];
}
function parseRoundsFromText(text) {
    var m = String(text || '').match(/(\d+)\s*serie/i);
    return m ? Math.max(1, Math.min(10, Number(m[1]))) : null;
}
async function findOrCreateExercise(src) { let name = (src.nome_esercizio || '').trim(); if (!name) return null; let e = S.exercises.find(x => x.name.toLowerCase() === name.toLowerCase()); if (e) return e; e = { id: uid(), name, primary: src.target || 'Da classificare', source: 'Import JSON utente', createdAt: now(), updatedAt: now() }; await Store.put('exercises', e); S.exercises.push(e); return e }

async function parseBlocks(arr, section, type) {
    var blocks = [];
    for (const item of Array.isArray(arr) ? arr : []) {
        var key = Object.keys(item || {})[0];
        var b = item[key];
        if (!b) continue;

        var exerciseEntries = Object.keys(b).filter(function (x) { return /^esercizio\d+$/.test(x); });
        var exCount = exerciseEntries.length;

        var resolvedType = mapType(b.tipo || type, section);
        var tipoLow = String(b.tipo || '').toLowerCase();
        var nomeLow = String(b.nome_circuito || '').toLowerCase();

        if (resolvedType !== 'Single' && exCount === 1 &&
            tipoLow.indexOf('circuito') === -1 &&
            nomeLow.indexOf('circuito') === -1) {
            resolvedType = 'Single';
        }

        if (tipoLow.indexOf('super') !== -1 || /super\s*serie/i.test(nomeLow)) {
            resolvedType = 'Superset';
        }

        var defaultRounds = 3;
        if (resolvedType === 'Single') {
            var single = b[exerciseEntries[0]] || {};
            var rdet = parseRoundsFromText(single.ripetizioni);
            if (rdet) defaultRounds = rdet;
        }

        var block = {
            id: uid(),
            section: section,
            type: resolvedType,
            label: b.nome_circuito || key,
            restText: b.recupero || '',
            restSec: parseRestToSeconds(b.recupero),
            rounds: defaultRounds,
            exerciseIds: [],
            exerciseTargets: {}
        };

        for (var i = 0; i < exerciseEntries.length; i++) {
            var exKey = exerciseEntries[i];
            var src = b[exKey] || {};
            var ex = await findOrCreateExercise(src);
            if (!ex) continue;

            var reps = src.ripetizioni || '';
            if (resolvedType === 'Single') {
                var cleaned = reps.replace(/^\s*\d+\s*serie\s*x?\s*/i, '').trim();
                if (cleaned) reps = cleaned;
            }

            block.exerciseIds.push(ex.id);
            block.exerciseTargets[ex.id] = {
                reps: reps,
                target: src.target || ''
            };
        }

        blocks.push(block);
    }
    return blocks;
}

