            var blocks = ctx() ? ctx().blocks : [];
            var bi = blocks.findIndex(function (bb) { return bb.id === first.blockId; });
            var inp = document.getElementById('kg_' + bi + '_' + first.exerciseId + '_' + first.setNo);
