function stats() {
    var done = completedSessions();
    if (!done.length) {
        return '<div class="card"><h2>Nessun allenamento ancora</h2><p class="muted">Completa il tuo primo workout per vedere qui i tuoi progressi.</p><div class="row" style="margin-top:10px"><button class="primary" onclick="go(\'home\')">Vai in Home</button></div></div>';
    }

    var totalVol = 0, totalDur = 0, totalSets = 0;
    for (var i = 0; i < done.length; i++) {
        totalVol += sessionVolume(done[i]);
        totalDur += Number(done[i].durationSec) || 0;
        totalSets += sessionSetsDone(done[i]);
    }
    var avgDur = done.length ? Math.round(totalDur / done.length) : 0;
    var avgVol = done.length ? Math.round(totalVol / done.length) : 0;
    var streak = streakDays();
    var prs = topPRs(8);
    var trend = recentSessions(10);
    var maxVol = 0;
    for (var i = 0; i < trend.length; i++) {
        var v = sessionVolume(trend[i]);
        if (v > maxVol) maxVol = v;
    }

    var hero = '<div class="card statHero primary">' +
        '<p class="metaLight">Progressi</p>' +
        '<div class="statHeroGrid">' +
        '<div><div class="statBig">' + done.length + '</div><div class="statSub">Workout</div></div>' +
        '<div><div class="statBig">' + fmtNum(totalVol) + '</div><div class="statSub">Volume kg</div></div>' +
        '<div><div class="statBig">' + streak + '</div><div class="statSub">Streak' + (streak === 1 ? ' giorno' : ' giorni') + '</div></div>' +
        '</div></div>';

    var quickGrid = '<div class="statQuickGrid">' +
        '<div class="card statCard"><div class="statValue">' + (avgDur > 0 ? fmtDurShort(avgDur) : '—') + '</div><div class="statLabel">Durata media</div></div>' +
        '<div class="card statCard"><div class="statValue">' + fmtNum(avgVol) + '</div><div class="statLabel">Volume medio</div></div>' +
        '<div class="card statCard"><div class="statValue">' + totalSets + '</div><div class="statLabel">Serie totali</div></div>' +
        '</div>';

    var chartHtml = '';
    if (trend.length) {
        var bars = trend.slice().reverse().map(function (s) {
            var v = sessionVolume(s);
            var pct = maxVol > 0 ? Math.max(3, Math.round(v / maxVol * 100)) : 0;
            return '<div class="barCol" title="' + esc(fmtNum(v)) + ' kg"><div class="barTrack"><div class="barFill" style="height:' + pct + '%"></div></div><div class="barLabel">' + esc(fmtShortDate(s.endedAt)) + '</div></div>';
        }).join('');
        var chartTitle = trend.length === 1 ? 'Volume ultima sessione' : 'Volume ultime ' + trend.length + ' sessioni';
        chartHtml = '<div class="card"><div class="between"><h3>' + chartTitle + '</h3><span class="pill">' + fmtNum(maxVol) + ' kg max</span></div><div class="barChart">' + bars + '</div></div>';
    }

    var prHtml = '';
    if (prs.length) {
        var rows = prs.map(function (p, i) {
            return '<div class="prRow"><span class="prRank">' + (i + 1) + '</span><div class="prMain"><div class="prName">' + esc(p.name) + '</div><div class="prMeta">' + esc(p.primary || '') + (p.when ? ' • ' + esc(fmtShortDate(p.when)) : '') + '</div></div><div class="prValue">' + p.kg + '<small>kg</small></div></div>';
        }).join('');
        prHtml = '<div class="card"><h3>Personal Records</h3><div class="prList">' + rows + '</div></div>';
    }

    var last = recentSessions(5);
    var lastHtml = '';
    if (last.length) {
        var rows2 = last.map(function (s) {
            var v = sessionVolume(s);
            var sets = sessionSetsDone(s);
            var lbl = sessionLabel(s);
            var durTxt = (Number(s.durationSec) || 0) > 0 ? fmtDurShort(s.durationSec) : '—';
            return '<div class="sessionRow"><div class="sessionMain"><div class="sessionName">' + esc(lbl) + '</div><div class="sessionMeta">' + esc(fmtShortDate(s.endedAt)) + ' • ' + durTxt + ' • ' + sets + ' serie</div></div><div class="sessionVol">' + fmtNum(v) + '<small>kg</small></div></div>';
        }).join('');
        lastHtml = '<div class="card"><h3>Ultime sessioni</h3><div class="sessionList">' + rows2 + '</div></div>';
    }

    return hero + quickGrid + chartHtml + prHtml + lastHtml;
}

